#!/usr/bin/env python3
"""Generate rust/LICENSE-THIRD-PARTY: notices for everything linked into
praatfan_rust binaries (Python wheels, praatfan-open-pipe, the WASM bundles).

    python3 rust/third-party/generate_notices.py           # rewrite the file
    python3 rust/third-party/generate_notices.py --check   # exit 1 if stale

Run it after any change to rust/Cargo.lock.  The crate list comes from
`cargo metadata` (features pipe+python+wasm, all target platforms), following
normal (non-build, non-dev) dependencies only and skipping proc-macro crates,
since neither ends up in the shipped binary.  License texts come from each
crate's own LICENSE/COPYING/NOTICE files; crates that ship none get a text from
rust/third-party/texts/ (FALLBACK below).  A crate with neither is an error.
"""

import json
import os
import subprocess
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
RUST = os.path.dirname(HERE)
TEXTS = os.path.join(HERE, "texts")
OUT = os.path.join(RUST, "LICENSE-THIRD-PARTY")

LICENSE_PREFIXES = ("LICEN", "COPYING", "COPYRIGHT", "NOTICE", "UNLICENSE")

# Crates whose published package ships no license file: the upstream
# repository's text, stored under texts/.
FALLBACK = {
    "faer": ["faer-LICENSE"],
    "faer-macros": ["faer-LICENSE"],
    "faer-traits": ["faer-LICENSE"],
    "equator": ["equator-LICENSE"],
    "equator-macro": ["equator-LICENSE"],
    "nano-gemm": ["nano-gemm-LICENSE"],
    "nano-gemm-c32": ["nano-gemm-LICENSE"],
    "nano-gemm-c64": ["nano-gemm-LICENSE"],
    "nano-gemm-core": ["nano-gemm-LICENSE"],
    "nano-gemm-f32": ["nano-gemm-LICENSE"],
    "nano-gemm-f64": ["nano-gemm-LICENSE"],
}
MPL_TEXT = "MPL-2.0.txt"

HEADER = """\
THIRD-PARTY SOFTWARE NOTICES — praatfan_rust
=============================================

praatfan_rust is MIT-licensed (see LICENSE).  Its compiled forms — the
praatfan_rust Python wheels, the praatfan-open-pipe binaries, and the WASM
bundles shipped in the praatfan Python package and the praatfan R package —
also contain the third-party code listed below, under the licenses
reproduced here.

This file is generated by rust/third-party/generate_notices.py; do not edit.

Source code for MPL-2.0 components
----------------------------------
The symphonia-* crates listed below are licensed under the Mozilla Public
License 2.0 and are used unmodified.  Their Source Code Form is available at
https://github.com/pdeljanov/Symphonia and from crates.io at the versions
listed (https://crates.io/crates/<name>/<version>).

"""

VENDORED = """\
=======================================================================
Vendored code: rust/src/smallft/ (real FFT used by the resampler)
=======================================================================

Lineage: FFTPACK (Paul N. Swarztrauber, NCAR, 1985) -> smallft.c from
OggSquish/Ogg Vorbis, as carried in Xiph.Org's speexdsp (with fftwrap.c by
Jean-Marc Valin) -> Rust translation in speexdsp-rs (Luca Barbato) -> this
copy, modified for f64 precision.

--- FFTPACK: UCAR license (NCAR's FFTPACK curators state that the FFTPACK5
--- license applies to the FFTPACK version 4 sources)

{fftpack}
--- speexdsp (smallft.c, fftwrap.c): Xiph.Org BSD license

{speexdsp}
--- Ogg Vorbis (origin of smallft.c): Xiph.Org BSD license

{vorbis}
--- speexdsp-rs (Rust translation): MIT license

{speexdsp_rs}
"""


def read(path):
    with open(path, encoding="utf-8", errors="replace") as f:
        text = f.read()
    return text.rstrip() + "\n"


def crates():
    meta = json.loads(subprocess.check_output(
        ["cargo", "metadata", "--format-version", "1", "--locked",
         "--features", "pipe,python,wasm"],
        cwd=RUST))
    pkgs = {p["id"]: p for p in meta["packages"]}
    nodes = {n["id"]: n for n in meta["resolve"]["nodes"]}
    root = meta["resolve"]["root"]

    def is_proc_macro(pid):
        return any("proc-macro" in t["kind"] for t in pkgs[pid]["targets"])

    seen, stack = set(), [root]
    while stack:
        pid = stack.pop()
        if pid in seen:
            continue
        seen.add(pid)
        for dep in nodes[pid]["deps"]:
            normal = any(k["kind"] is None for k in dep["dep_kinds"])
            if normal and not is_proc_macro(dep["pkg"]):
                stack.append(dep["pkg"])
    seen.discard(root)
    return sorted((pkgs[p] for p in seen),
                  key=lambda p: (p["name"], p["version"]))


def license_texts(pkg):
    crate_dir = os.path.dirname(pkg["manifest_path"])
    files = sorted(
        f for f in os.listdir(crate_dir)
        if f.upper().startswith(LICENSE_PREFIXES)
        and os.path.isfile(os.path.join(crate_dir, f)))
    if files:
        return [(f, read(os.path.join(crate_dir, f))) for f in files]
    if pkg["name"] in FALLBACK:
        return [(f"{f} (upstream repository)", read(os.path.join(TEXTS, f)))
                for f in FALLBACK[pkg["name"]]]
    if pkg.get("license") == "MPL-2.0":
        return None  # MPL text is reproduced once, at the end
    raise SystemExit(f"error: {pkg['name']} {pkg['version']} ships no license "
                     f"file; add its text to rust/third-party/texts/ and "
                     f"FALLBACK")


def render():
    parts = [HEADER]
    parts.append(VENDORED.format(
        fftpack=read(os.path.join(TEXTS, "fftpack5-UCAR.txt")),
        speexdsp=read(os.path.join(TEXTS, "speexdsp-COPYING")),
        vorbis=read(os.path.join(TEXTS, "vorbis-COPYING")),
        speexdsp_rs=read(os.path.join(TEXTS, "speexdsp-rs-LICENSE"))))
    pkgs = crates()
    parts.append("=" * 71 + "\nRust crates linked into the binaries "
                 f"({len(pkgs)})\n" + "=" * 71 + "\n\n")
    for p in pkgs:
        parts.append(f"{p['name']} {p['version']} — {p.get('license')}\n")
    parts.append("\n")
    # Identical texts (e.g. the Apache-2.0 text most crates ship) are printed
    # once, under a label [Tn]; each crate lists which labels apply to it.
    labels = {}  # normalized text -> label
    unique = []  # (label, text) in first-use order

    def label_for(text):
        key = "\n".join(line.rstrip() for line in text.strip().splitlines())
        if key not in labels:
            labels[key] = f"T{len(unique) + 1}"
            unique.append((labels[key], text))
        return labels[key]

    parts.append("=" * 71 + "\nLicense files per crate (texts in the next "
                 "section)\n" + "=" * 71 + "\n\n")
    for p in pkgs:
        texts = license_texts(p)
        if texts is None:
            texts = [("Mozilla Public License 2.0",
                      read(os.path.join(TEXTS, MPL_TEXT)))]
        refs = ", ".join(f"{name} [{label_for(text)}]" for name, text in texts)
        repo = f"  <{p['repository']}>" if p.get("repository") else ""
        parts.append(f"{p['name']} {p['version']}{repo}\n    {refs}\n")
    parts.append("\n" + "=" * 71 + "\nLicense texts\n" + "=" * 71 + "\n\n")
    for label, text in unique:
        parts.append("-" * 71 + f"\n[{label}]\n" + "-" * 71 + f"\n\n{text}\n")
    return "".join(parts)


def main():
    text = render()
    if "--check" in sys.argv[1:]:
        try:
            current = read(OUT) if os.path.exists(OUT) else ""
        except OSError:
            current = ""
        if current.rstrip() != text.rstrip():
            print("rust/LICENSE-THIRD-PARTY is stale; run "
                  "python3 rust/third-party/generate_notices.py",
                  file=sys.stderr)
            return 1
        print("rust/LICENSE-THIRD-PARTY is up to date")
        return 0
    with open(OUT, "w", encoding="utf-8") as f:
        f.write(text)
    print(f"wrote {OUT}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
